<?php require 'db.php';$s=$pdo->prepare("SELECT u.id,u.first_name,u.last_name,u.student_id,u.username,u.email,u.contact_number,u.role,s.name section_name,d.code program FROM users u JOIN sections s ON s.id=u.section_id JOIN departments d ON d.id=s.department_id WHERE u.id=:i");$s->execute([':i'=>(int)($_GET['user_id']??0)]);$u=$s->fetch(PDO::FETCH_ASSOC);if(!$u){http_response_code(404);echo json_encode(['success'=>false,'message'=>'User not found.']);exit;}echo json_encode(['success'=>true,'message'=>'Profile loaded.','user'=>$u]);?>